const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lasVegas = ee.Geometry.Point([-115.1373, 36.1716]); // Approximate center of Las Vegas, Nevada
  const startDate = '2017-06-15T00:00:00';
  const endDate = '2017-06-21T23:59:59'; // End of the day on June 21st

  // 2. Data Acquisition & Check
  let temperatureCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(lasVegas)
    .select('temperature_2m');

  const collectionSize = await temperatureCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No ERA5-Land hourly data found for Las Vegas between June 15-21, 2017.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Function to convert Kelvin to Fahrenheit
  const toFahrenheit = function(image) {
    // Temperature is in Kelvin. Convert to Celsius, then Fahrenheit.
    // Celsius = Kelvin - 273.15
    // Fahrenheit = (Celsius * 9/5) + 32
    return image.subtract(273.15).multiply(9/5).add(32)
      .rename('temperature_fahrenheit')
      .copyProperties(image, ['system:time_start']);
  };

  const fahrenheitCollection = temperatureCollection.map(toFahrenheit);

  // Find the maximum temperature over the entire period
  const maxTempImage = fahrenheitCollection.max();

  // Calculate the maximum temperature within the Las Vegas point geometry
  // Use a coarse scale appropriate for ERA5-Land data (e.g., 1000m or 3000m)
  // ERA5-Land resolution is ~9km, so 1000m scale is fine.
  const stats = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max().setOutputs(['max_temp']),
    geometry: lasVegas,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTempFahrenheit = stats ? stats['temperature_fahrenheit_max'] : null;

  // Validate pixel count (implicitly done by reduceRegion; if no data, maxTempFahrenheit would be null)
  // For reanalysis products like ERA5-Land, "valid pixels" is less about masking and more about data existence
  if (maxTempFahrenheit === null || isNaN(maxTempFahrenheit)) {
    console.log("Calculation failed or no valid pixels after processing.");
    console.log("C3"); // Or C2 if specifically zero non-masked pixels are needed, but ERA5 is usually full.
    return;
  }

  // 4. Validation & Final Answer
  const threshold = 130; // degrees Fahrenheit

  console.log(`Collection size: ${collectionSize}`);
  console.log(`Max temperature recorded in Las Vegas (June 15-21, 2017): ${maxTempFahrenheit.toFixed(2)} °F`);

  if (maxTempFahrenheit > threshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
